def _load_tum() -> dict:
    tum_path = _paths.config_dir() / "tum_status.yaml"
    if not tum_path.exists():
        return {"keys": {}}
    with open(tum_path) as f:
        return yaml.safe_load(f) or {}


def _save_tum(data: dict) -> None:
    tum_path = _paths.config_dir() / "tum_status.yaml"
    tum_path.parent.mkdir(parents=True, exist_ok=True)
    with open(tum_path, "w") as f:
        yaml.dump(data, f, allow_unicode=True, default_flow_style=False)


def _detect_provider(key_value: str) -> str:
    """Auto-detect provider from API key prefix."""
    if key_value.startswith(("sk-ant-api03-", "sk-ant-api04-", "sk-ant-")):
        return "anthropic"
    if key_value.startswith("sk-"):
        return "openai"
    if key_value.startswith(("AIza", "ya29.")):
        return "google"
    # Gemini API keys are typically 39-char alphanumeric without a known prefix —
    # fall back to trying the Gemini endpoint when provider is unknown.
    return "unknown"


