@router.get("/tum/status")
def check_tum_status():
    """Probe the TUM service. Uses /admin/stats/overview with admin token."""
    import httpx

    base = _tum_base_url()
    headers = _tum_headers()
    try:
        resp = httpx.get(f"{base.rstrip('/')}/admin/stats/overview", headers=headers, timeout=5)
        if resp.status_code == 200:
            data = resp.json()
            return {"reachable": True, "status": "ok", "detail": data}
        if resp.status_code in (401, 403):
            return {"reachable": True, "status": "unauthorized", "error": "Admin Token 无效或未设置"}
        return {"reachable": True, "status": "error", "http_status": resp.status_code}
    except httpx.ConnectError:
        return {"reachable": False, "status": "unreachable", "error": f"无法连接 {base}"}
    except Exception as e:
        return {"reachable": False, "status": "error", "error": str(e)}


@router.get("/tum/keys")
def list_tum_keys():
    """Proxy TUM /admin/keys — list all keys from TUM service."""
    import httpx

    base = _tum_base_url()
    headers = _tum_headers()
    if not headers:
        raise HTTPException(400, detail="Admin Token 未设置")
    try:
        resp = httpx.get(f"{base.rstrip('/')}/admin/keys", headers=headers, timeout=5)
        if resp.status_code == 200:
            return resp.json()
        raise HTTPException(resp.status_code, detail=f"TUM returned {resp.status_code}")
    except httpx.ConnectError:
        raise HTTPException(502, detail=f"无法连接 TUM: {base}")
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(502, detail=str(e))


