"""Symmetric encryption for secrets (Admin Tokens, API Keys).

Uses Fernet (AES-128-CBC + HMAC-SHA256) with a key derived from the machine ID.
Goal: prevent plain-text exposure if files are read by the Agent or leaked —
this is NOT a substitute for OS-level access control.
"""

from __future__ import annotations

import base64
import hashlib
import uuid
from pathlib import Path

from cryptography.fernet import Fernet, InvalidToken

# Deterministic salt — changing this invalidates all stored secrets.
_SALT = b"agent-ml-research-tum-v1"


def _derive_key() -> bytes:
    """Derive a Fernet key from the machine's MAC address + salt."""
    machine_id = str(uuid.getnode()).encode()
    raw = hashlib.pbkdf2_hmac("sha256", machine_id, _SALT, iterations=100_000, dklen=32)
    return base64.urlsafe_b64encode(raw)


_fernet: Fernet | None = None


def _get_fernet() -> Fernet:
    global _fernet
    if _fernet is None:
        _fernet = Fernet(_derive_key())
    return _fernet


def encrypt(plaintext: str) -> str:
    """Encrypt a string, return URL-safe base64 ciphertext."""
    return _get_fernet().encrypt(plaintext.encode()).decode()


def decrypt(ciphertext: str) -> str | None:
    """Decrypt ciphertext. Returns None if invalid/corrupted."""
    try:
        return _get_fernet().decrypt(ciphertext.encode()).decode()
    except (InvalidToken, Exception):
        return None


# --- File-level helpers (for admin token / API keys) ---

def save_secret(path: Path, plaintext: str) -> None:
    """Encrypt and write a secret to a file."""
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(encrypt(plaintext))


def load_secret(path: Path) -> str | None:
    """Read and decrypt a secret from a file. Returns None if missing/invalid."""
    if not path.exists():
        return None
    ciphertext = path.read_text().strip()
    if not ciphertext:
        return None
    return decrypt(ciphertext)

_TUM_DEFAULT_PORT = 8001


def _start_tum_if_configured(logger) -> "subprocess.Popen | None":
    """Start the TUM (Token Usage Manager) service as a subprocess."""
    import subprocess
    import yaml as _yaml

    # Check tum_status.yaml for config
    tum_cfg_path = _ws_root / "config" / "tum_status.yaml"
    tum_cfg: dict = {}
    if tum_cfg_path.exists():
        with open(tum_cfg_path) as f:
            tum_cfg = _yaml.safe_load(f) or {}

    if not tum_cfg.get("auto_start", False):
        return None

    tum_dir = Path(tum_cfg.get("tum_dir", str(_TUM_DIR)))
    port = tum_cfg.get("port", _TUM_DEFAULT_PORT)

    if not (tum_dir / "backend" / "app" / "main.py").exists():
        logger.warning("[startup] TUM auto_start enabled but TUM not found at %s", tum_dir)
        return None

    # Read admin token for TUM env
    from core.crypto import load_secret
    admin_token = load_secret(_ws_root / "config" / "tum_admin_token.enc")
    env = {**os.environ, "PORT": str(port), "HOST": "127.0.0.1"}
    if admin_token:
        env["ADMIN_TOKEN"] = admin_token

    try:
        proc = subprocess.Popen(
            ["uv", "run", "uvicorn", "app.main:app", "--host", "127.0.0.1", "--port", str(port)],
            cwd=str(tum_dir / "backend"),
            env=env,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.PIPE,
        )
        logger.info("[startup] TUM started (pid=%s, port=%s, dir=%s)", proc.pid, port, tum_dir)
        print(f"TUM 服务已启动 (pid={proc.pid}, port={port})")
        return proc
    except Exception as e:
        logger.warning("[startup] TUM start failed: %s", e)
        print(f"TUM 启动失败: {e}")
        return None


